namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string? CustomerEmail { get; set; }
    public string? Notes { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<Shipment>> GetShipmentsByCustomerAsync(string email);
    Task<Shipment> CreateShipmentAsync(Shipment shipment);
    Task<Shipment> UpdateShipmentAsync(Shipment shipment);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments/my") ?? [];
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{shipment.Id}", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
    {
        return await db.Shipments
            .Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.CreatedDate)
            .ToListAsync();
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.CreatedDate = DateTime.UtcNow;
        if (string.IsNullOrEmpty(shipment.TrackingNumber))
        {
            shipment.TrackingNumber = $"TRK-{Guid.NewGuid().ToString("N")[..8].ToUpper()}";
        }
        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var existing = await db.Shipments.FindAsync(shipment.Id)
            ?? throw new KeyNotFoundException($"Shipment {shipment.Id} not found");
        existing.Origin = shipment.Origin;
        existing.Destination = shipment.Destination;
        existing.Status = shipment.Status;
        existing.EstimatedDelivery = shipment.EstimatedDelivery;
        existing.CustomerEmail = shipment.CustomerEmail;
        existing.Notes = shipment.Notes;
        await db.SaveChangesAsync();
        return existing;
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Controllers;

[ApiController]
[Route("api/[controller]")]
public class ShipmentsController(IShipmentService shipmentService) : ControllerBase
{
    [HttpGet]
    [Authorize(Roles = "Dispatcher")]
    public async Task<ActionResult<List<Shipment>>> GetAll()
    {
        return await shipmentService.GetAllShipmentsAsync();
    }

    [HttpGet("track/{trackingNumber}")]
    [Authorize]
    public async Task<ActionResult<Shipment>> GetByTrackingNumber(string trackingNumber)
    {
        var shipment = await shipmentService.GetShipmentByTrackingNumberAsync(trackingNumber);
        if (shipment is null) return NotFound();
        return shipment;
    }

    [HttpGet("my")]
    [Authorize]
    public async Task<ActionResult<List<Shipment>>> GetMyShipments()
    {
        var email = User.FindFirstValue(ClaimTypes.Email);
        if (string.IsNullOrEmpty(email)) return new List<Shipment>();
        return await shipmentService.GetShipmentsByCustomerAsync(email);
    }

    [HttpPost]
    [Authorize(Roles = "Dispatcher")]
    public async Task<ActionResult<Shipment>> Create(Shipment shipment)
    {
        var created = await shipmentService.CreateShipmentAsync(shipment);
        return CreatedAtAction(nameof(GetByTrackingNumber),
            new { trackingNumber = created.TrackingNumber }, created);
    }

    [HttpPut("{id}")]
    [Authorize(Roles = "Dispatcher")]
    public async Task<ActionResult<Shipment>> Update(int id, Shipment shipment)
    {
        shipment.Id = id;
        return await shipmentService.UpdateShipmentAsync(shipment);
    }
}

