+using System.Security.Claims;
+using Microsoft.AspNetCore.Authorization;
+using Microsoft.AspNetCore.Mvc;
+using ShipmentTracker.Client.Models;
+using ShipmentTracker.Client.Services;
+
+namespace ShipmentTracker.Controllers;
+
+[ApiController]
+[Route("api/[controller]")]
+public class ShipmentsController(IShipmentService shipmentService) : ControllerBase
+{
+    [HttpGet]
+    [Authorize(Roles = "Dispatcher")]
+    public async Task<ActionResult<List<Shipment>>> GetAll()
+    {
+        return await shipmentService.GetAllShipmentsAsync();
+    }
+
+    [HttpGet("track/{trackingNumber}")]
+    [Authorize]
+    public async Task<ActionResult<Shipment>> GetByTrackingNumber(string trackingNumber)
+    {
+        var shipment = await shipmentService.GetShipmentByTrackingNumberAsync(trackingNumber);
+        if (shipment is null) return NotFound();
+        return shipment;
+    }
+
+    [HttpGet("my")]
+    [Authorize]
+    public async Task<ActionResult<List<Shipment>>> GetMyShipments()
+    {
+        var email = User.FindFirstValue(ClaimTypes.Email);
+        if (string.IsNullOrEmpty(email)) return new List<Shipment>();
+        return await shipmentService.GetShipmentsByCustomerAsync(email);
+    }
+
+    [HttpPost]
+    [Authorize(Roles = "Dispatcher")]
+    public async Task<ActionResult<Shipment>> Create(Shipment shipment)
+    {
+        var created = await shipmentService.CreateShipmentAsync(shipment);
+        return CreatedAtAction(nameof(GetByTrackingNumber),
+            new { trackingNumber = created.TrackingNumber }, created);
+    }
+
+    [HttpPut("{id}")]
+    [Authorize(Roles = "Dispatcher")]
+    public async Task<ActionResult<Shipment>> Update(int id, Shipment shipment)
+    {
+        shipment.Id = id;
+        return await shipmentService.UpdateShipmentAsync(shipment);
+    }
+}
+

