    private Shipment editShipment = new();
    private int? editingId;
    private bool showCreateForm;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Error loading shipments: {ex.Message}";
        }
    }

    private void ShowCreateForm() => showCreateForm = !showCreateForm;

    private async Task CreateShipment()
    {
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            newShipment = new();
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Error creating shipment: {ex.Message}";
        }
    }

    private void StartEdit(Shipment shipment)
    {
        editingId = shipment.Id;
        editShipment = new Shipment
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            EstimatedDelivery = shipment.EstimatedDelivery,
            CustomerEmail = shipment.CustomerEmail,
            Notes = shipment.Notes,
            CreatedDate = shipment.CreatedDate
        };
    }

    private async Task SaveEdit()
    {
        try
        {
            await ShipmentService.UpdateShipmentAsync(editShipment);
            editingId = null;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Error updating shipment: {ex.Message}";
        }
    }

    private void CancelEdit() => editingId = null;

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g., TRK-A1B2C3D4)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (isLoading)
{
    <p><em>Searching...</em></p>
}
else if (searched && shipment is null)
{
    <div class="alert alert-warning">
        <h5>Shipment not found</h5>
        <p>No shipment was found with tracking number "<strong>@searchedNumber</strong>". Please check the number and try again.</p>
    </div>
}
else if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header bg-dark text-white">
            <h4 class="mb-0">📦 Shipment <code class="text-light">@shipment.TrackingNumber</code></h4>
        </div>
        <div class="card-body">
            <div class="row mb-3">
                <div class="col-md-4">
                    <strong>Origin:</strong><br />@shipment.Origin
                </div>
                <div class="col-md-4">
                    <strong>Destination:</strong><br />@shipment.Destination
                </div>
                <div class="col-md-4">
                    <strong>Status:</strong><br />
                    <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
                </div>
            </div>
            <div class="row mb-4">
                <div class="col-md-4">
                    <strong>Created:</strong><br />@shipment.CreatedDate.ToString("MMM dd, yyyy")
                </div>
                <div class="col-md-4">
                    <strong>Estimated Delivery:</strong><br />@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")
                </div>
                <div class="col-md-4">
                    <strong>Notes:</strong><br />@(shipment.Notes ?? "—")
                </div>
            </div>

            @* Status Timeline *@
            <h5 class="mt-4 mb-3">Shipment Progress</h5>
            <div class="d-flex justify-content-between position-relative mb-3">
                <div class="position-absolute w-100" style="top: 14px; left: 0; z-index: 0;">
                    <div class="progress" style="height: 4px;">
                        <div class="progress-bar bg-success" style="width: @(GetProgressPercent(shipment.Status))%"></div>
                    </div>
                </div>
                @foreach (var stage in stages)
                {
                    var isActive = (int)shipment.Status >= (int)stage;
                    var isCurrent = shipment.Status == stage;
                    <div class="text-center position-relative" style="z-index: 1; flex: 1;">
                        <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light border") @(isCurrent ? "border-3 border-success" : "")"
                             style="width: 30px; height: 30px; font-size: 0.75rem;">
                            @if (isActive) { <span>✓</span> } else { <span>○</span> }
                        </div>
                        <div class="small mt-1 @(isCurrent ? "fw-bold" : "")">@stage</div>
                    </div>
                }
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;
    private bool isLoading;

    private static readonly ShipmentStatus[] stages = [
        ShipmentStatus.Pending,
        ShipmentStatus.PickedUp,
        ShipmentStatus.InTransit,
        ShipmentStatus.OutForDelivery,
        ShipmentStatus.Delivered
    ];

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        searched = false;
        shipment = null;
        try
        {
            searchedNumber = trackingNumber.Trim();
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
            searched = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 0,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 0,
        _ => 0
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

