+@page "/my-shipments"
+@using Microsoft.AspNetCore.Authorization
+@using Microsoft.AspNetCore.Components.Authorization
+@attribute [Authorize]
+@rendermode InteractiveAuto
+@inject IShipmentService ShipmentService
+@inject AuthenticationStateProvider AuthStateProvider
+
+<PageTitle>My Shipments</PageTitle>
+
+<h2 class="mb-4">My Shipments</h2>
+
+@if (isLoading)
+{
+    <p><em>Loading your shipments...</em></p>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger">@errorMessage</div>
+}
+else if (shipments is null || shipments.Count == 0)
+{
+    <div class="alert alert-info">
+        <h5>No shipments found</h5>
+        <p>You don't have any shipments associated with your account yet. Once a shipment is created with your email address, it will appear here.</p>
+    </div>
+}
+else
+{
+    <div class="row g-3">
+        @foreach (var shipment in shipments)
+        {
+            <div class="col-md-6 col-lg-4">
+                <div class="card h-100 shadow-sm">
+                    <div class="card-body">
+                        <div class="d-flex justify-content-between align-items-start mb-2">
+                            <h5 class="card-title mb-0"><code>@shipment.TrackingNumber</code></h5>
+                            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
+                        </div>
+                        <p class="card-text mb-1"><strong>From:</strong> @shipment.Origin</p>
+                        <p class="card-text mb-1"><strong>To:</strong> @shipment.Destination</p>
+                        <p class="card-text mb-1">
+                            <strong>Est. Delivery:</strong>
+                            @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "N/A")
+                        </p>
+                        @if (!string.IsNullOrEmpty(shipment.Notes))
+                        {
+                            <p class="card-text text-muted small">@shipment.Notes</p>
+                        }
+                    </div>
+                    <div class="card-footer text-muted small">
+                        Created: @shipment.CreatedDate.ToString("MMM dd, yyyy")
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private List<Shipment>? shipments;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            var authState = await AuthStateProvider.GetAuthenticationStateAsync();
+            var email = authState.User.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value
+                     ?? authState.User.FindFirst("email")?.Value
+                     ?? authState.User.Identity?.Name;
+
+            if (!string.IsNullOrEmpty(email))
+            {
+                shipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Error loading shipments: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

