3. using Microsoft.EntityFrameworkCore;
4. using ShipmentTracker.Client.Pages;
5. using ShipmentTracker.Client.Services;
6. using ShipmentTracker.Components;
7. using ShipmentTracker.Components.Account;
8. using ShipmentTracker.Data;
9. using ShipmentTracker.Services;
10. 
11. var builder = WebApplication.CreateBuilder(args);
12. 
13. // Add services to the container.
14. builder.Services.AddControllers();
15. builder.Services.AddRazorComponents()
16.     .AddInteractiveServerComponents()
17.     .AddInteractiveWebAssemblyComponents()
18.     .AddAuthenticationStateSerialization();
19. 
20. builder.Services.AddCascadingAuthenticationState();
21. builder.Services.AddScoped<IdentityRedirectManager>();
22. builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();
23. 
24. builder.Services.AddAuthentication(options =>
25.     {
26.         options.DefaultScheme = IdentityConstants.ApplicationScheme;
27.         options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
28.     })
29.     .AddIdentityCookies();
30. 
31. var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
32. builder.Services.AddDbContext<ApplicationDbContext>(options =>
33.     options.UseSqlite(connectionString));
34. builder.Services.AddDatabaseDeveloperPageExceptionFilter();
35. 
36. builder.Services.AddIdentityCore<ApplicationUser>(options =>
37.     {
38.         options.SignIn.RequireConfirmedAccount = true;
39.         options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
40.     })
41.     .AddRoles<IdentityRole>()
42.     .AddEntityFrameworkStores<ApplicationDbContext>()
43.     .AddSignInManager()
44.     .AddDefaultTokenProviders();
45. 
46. builder.Services.AddScoped<IShipmentService, ServerShipmentService>();
47. 
48. builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();
49. 
50. var app = builder.Build();
51. 
52. // Seed roles
53. using (var scope = app.Services.CreateScope())
54. {
55.     var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
56.     foreach (var role in new[] { "Dispatcher", "Customer" })
57.     {
58.         if (!await roleManager.RoleExistsAsync(role))
59.         {
60.             await roleManager.CreateAsync(new IdentityRole(role));
61.         }
62.     }
63. }
64. 
65. // Configure the HTTP request pipeline.
66. if (app.Environment.IsDevelopment())
67. {
68.     app.UseWebAssemblyDebugging();
69.     app.UseMigrationsEndPoint();
70. }
71. else
72. {
73.     app.UseExceptionHandler("/Error", createScopeForErrors: true);
